import{_ as t,c as d,o,ag as r}from"./chunks/framework.DCv_I274.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"operations/troubleshooting.md","filePath":"operations/troubleshooting.md","lastUpdated":null}'),a={name:"operations/troubleshooting.md"};function n(s,e,i,c,h,l){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Common errors, what they mean, and the fix.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>could not find driver</code></td><td><code>pdo_mysql</code> not enabled</td><td>enable <code>extension=pdo_mysql</code> in <code>php.ini</code> (<code>php --ini</code> shows which file)</td></tr><tr><td><code>SQLSTATE[HY000] [1045] Access denied</code></td><td>wrong <code>DB_USERNAME</code> / <code>DB_PASSWORD</code></td><td>fix <code>.env</code>, then <code>php artisan config:clear</code></td></tr><tr><td><code>SQLSTATE[HY000] [1049] Unknown database</code></td><td>database not created</td><td><code>CREATE DATABASE ...</code> (see <a href="/start/configure-environment">Configure the environment</a>)</td></tr><tr><td><code>No application encryption key has been specified</code></td><td>empty <code>APP_KEY</code></td><td><code>php artisan key:generate</code></td></tr><tr><td><code>laravel: command not found</code></td><td>Composer&#39;s global bin not in PATH</td><td>add it to PATH, or use <code>composer create-project</code></td></tr><tr><td>Changes to <code>.env</code> ignored</td><td>config is cached</td><td><code>php artisan optimize:clear</code></td></tr></tbody></table><h2 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>1067 Invalid default value for &#39;expires_at&#39;</code></td><td>a required <code>timestamp()</code> column on a MySQL server with <code>explicit_defaults_for_timestamp=OFF</code></td><td>use <code>dateTime()</code> for required time columns</td></tr><tr><td><code>1452 Cannot add or update a child row: a foreign key constraint fails</code></td><td>inserting a row that points at a missing parent</td><td>seed/create the parent first; check seeder order</td></tr><tr><td><code>1451 Cannot delete or update a parent row</code></td><td>deleting a row that others still reference (<code>restrictOnDelete</code>)</td><td>delete or detach the children first, or soft delete</td></tr><tr><td><code>Base table or view not found</code></td><td>migration not run, or wrong migration order</td><td><code>php artisan migrate:status</code>; parent tables need older timestamps</td></tr><tr><td><code>Column not found ... order clause</code></td><td>a sort key reached SQL</td><td>add an allow-list in <code>implementSort()</code></td></tr></tbody></table><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>Login: <code>REFRESH_TOKEN_PEPPER is not set</code></td><td>missing pepper</td><td>generate it (see <a href="/foundations/09-refresh-sessions">Refresh sessions</a>), then <code>config:clear</code></td></tr><tr><td><code>JWT key not found at ...</code></td><td>keys not generated or wrong path</td><td>generate the key pair; check <code>JWT_PRIVATE_KEY_PATH</code></td></tr><tr><td>Login / refresh: <strong>403</strong> <code>Request origin is not allowed</code></td><td>frontend origin not trusted</td><td>add it to <code>AUTH_TRUSTED_ORIGINS</code> (and <code>CORS_ALLOWED_ORIGINS</code>)</td></tr><tr><td>Login / refresh: <strong>403</strong> <code>Missing required X-Requested-With header</code></td><td>called from Postman/curl without an Origin</td><td>send <code>X-Requested-With: XMLHttpRequest</code></td></tr><tr><td>Every call <strong>401</strong> right after login</td><td>request has no <code>Authorization: Bearer</code> header, or <code>Accept</code> missing so a redirect happened</td><td>send both headers</td></tr><tr><td>Refresh always <strong>401</strong> <code>refresh_missing</code></td><td>cookie not sent</td><td>frontend must use <code>credentials: &#39;include&#39;</code>; the call must go to <code>/api/v1/auth/...</code> (cookie path)</td></tr><tr><td>Refresh <strong>409</strong></td><td>two tabs refreshed at once</td><td>retry the original request; don&#39;t log out</td></tr><tr><td>Users logged out after deploying</td><td>pepper or keys changed</td><td>expected; keep them stable per environment</td></tr><tr><td><code>Auth guard [api] is not defined</code> / driver <code>jwt</code> not supported</td><td><code>AuthServiceProvider</code> not registered</td><td>add it to <code>bootstrap/providers.php</code></td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><strong>403</strong> <code>You do not have permission to ...</code></td><td>the user&#39;s group lacks it</td><td>grant it in <code>data/rbac.php</code> + seed, or through <code>PUT /user-groups/{id}/permissions</code></td></tr><tr><td>New sub-module never granted</td><td>name typo between routes and seed data</td><td>use the <code>SubModules</code> constants; the seeder stops on unknown names</td></tr><tr><td>Admin gets 403</td><td>admin&#39;s <code>user_role_id</code> isn&#39;t 1</td><td>check <code>UserRoles::ADMINISTRATOR</code> matches the seeded id</td></tr></tbody></table><h2 id="browser-frontend" tabindex="-1">Browser / frontend <a class="header-anchor" href="#browser-frontend" aria-label="Permalink to &quot;Browser / frontend&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>Console: <code>blocked by CORS policy</code></td><td>origin not allowed, or credentials with <code>*</code></td><td>exact origins in <code>config/cors.php</code>, <code>supports_credentials: true</code></td></tr><tr><td>Blade form: <strong>419 Page Expired</strong></td><td>missing <code>@csrf</code> or the session expired</td><td>add <code>@csrf</code>; reload the page</td></tr><tr><td>Blade: <code>Vite manifest not found</code></td><td>assets not built</td><td><code>npm run dev</code> (local) or <code>npm run build</code></td></tr><tr><td>API returns an HTML page</td><td>error without <code>Accept: application/json</code></td><td>send the header; <code>shouldRenderJsonWhen</code> (step 03) covers <code>/api/*</code></td></tr></tbody></table><h2 id="where-to-look" tabindex="-1">Where to look <a class="header-anchor" href="#where-to-look" aria-label="Permalink to &quot;Where to look&quot;">​</a></h2><ol><li>The response <code>message</code> (full details when <code>APP_DEBUG=true</code>).</li><li><code>storage/logs/laravel.log</code>.</li><li>The activity log (every 5xx is recorded with its payload).</li><li><code>php artisan route:list -v</code> for routes and their middleware.</li><li><code>php artisan tinker</code> to try queries and services directly.</li></ol>',14)])])}const g=t(a,[["render",n]]);export{u as __pageData,g as default};
